-- Verified real tour catalog import.
-- Source: danangtrip-crawler/data/verified-real-tour-catalog-cloudinary-20260607.json
-- Policy:
--   - upsert by slug, never delete historical tours or relations;
--   - imported tours remain inactive until editorial/admin approval;
--   - source facts remain in itinerary/inclusions/exclusions;
--   - all media URLs use the verified Cloudinary catalog;
--   - future schedules are operational data generated at seed runtime.

BEGIN;

CREATE TEMP TABLE verified_real_tour_import (
    slug varchar(220) PRIMARY KEY,
    name varchar(200) NOT NULL,
    category_slug varchar(220) NOT NULL,
    description text NOT NULL,
    short_desc varchar(500) NOT NULL,
    itinerary json NOT NULL,
    inclusions json NOT NULL,
    exclusions json NOT NULL,
    price_adult numeric(12,2) NOT NULL,
    price_child numeric(12,2) NOT NULL,
    price_infant numeric(12,2) NOT NULL,
    discount_percent integer NOT NULL,
    duration varchar(50),
    start_time varchar(50),
    meeting_point varchar(255),
    max_people integer NOT NULL,
    min_people integer NOT NULL,
    thumbnail text,
    images json NOT NULL,
    source_url text NOT NULL,
    duration_days integer NOT NULL,
    import_order integer NOT NULL
) ON COMMIT DROP;

INSERT INTO verified_real_tour_import VALUES
    ('recrawl-018-venusvietnamtravel-afternoon-ba-na-hills-golden-bridge-dragon-bridge-by-night-tour-venustravel', 'AFTERNOON BA NA HILLS – GOLDEN BRIDGE & DRAGON BRIDGE BY NIGHT TOUR', 'tour-ba-na-hills', 'Chương trình tham quan Da Nang, Hoi An, Hue, Ba Na Hills với thời lượng 7.5 hours. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://venusvietnamtravel.com/afternoon-ba-na-hills-golden-bridge-dragon-bridge-by-night-tour/', 'Tour Da Nang, Hoi An, Hue, Ba Na Hills, thời lượng 7.5 hours, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["11:30–19:00 Pick-up & Join the tour","Pick Up Our Minivan and a tour guide pick you up at the hotel lobby","Ba Na Hills Check-in Ba Na Hills with the Golden Bridge and take part in many interesting activities.","Return to Ba Na Hills 5:00 PM: After freely exploring, we will gather together and return the cable car to leave Ba Na Hills.","Dragon Bridge Take the photo with Dragon Bridge by night in 15 minutes","19:30–20:00 Back to your hotel.","Drop Off Drop off at your hotel in Hoi An or Danang. End of our service."]'::json, '["Two way hotel pickup and drop off.","English-speaking tour guide","The ticket for return cable cars.","Local dinner","Golden Bridge, Le Jardin D''mour, Fantasy Park, Moon Castle, French Village, ...","A bottle of water"]'::json, '["Personal expense services not mentioned above","Drinks","Tips & gratuities for guides and drivers"]'::json, 1540750.0, 0.0, 0.0, 0, '7.5 hours', NULL, 'Depart from Hoi An / Da Nang / Hue Depart from Ha Noi Depart from Ho Chi Minh Pakage T', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804996/danangtrip/tours/bana-hills-afternoon-night/tour-001__p01__venus-video-scaled.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804996/danangtrip/tours/bana-hills-afternoon-night/tour-001__p01__venus-video-scaled.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804999/danangtrip/tours/bana-hills-afternoon-night/tour-001__p02__pexels-28297412.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780805002/danangtrip/tours/bana-hills-afternoon-night/tour-001__p03__pexels-20602155.jpg"]'::json, 'https://venusvietnamtravel.com/afternoon-ba-na-hills-golden-bridge-dragon-bridge-by-night-tour/', 1, 1),
    ('vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port', 'Ba Na Hills And Golden Bridge Tour From Tien Sa Port', 'tour-ba-na-hills', 'Chương trình tham quan Da Nang, Hoi An, Hue, Ba Na Hills với thời lượng 1 Day. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/ba-na-hills-and-golden-bridge-tour-from-tien-sa/', 'Tour Da Nang, Hoi An, Hue, Ba Na Hills, thời lượng 1 Day, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["Our driver and guide will pick you up at Tien Sa Port with a welcome board with your name and then transfer to Ba Na Hills. You can choose Pickup inside of the port or Pickup outside of the port.","Upon arrival at Bana Hills, get on a cable car and admire the stunning view from the lush nature and distant coastline. Afterward, walk around the iconic Golden Bridge - Hands of God, and immerse yourself in the charming Le Jardin D’Amour flower garden. Also, lost in the ancient","Finish Ba Na Hills and Golden Bridge Tour From Tien Sa Port . Goodbye, and thank you for choosing VM Travel to explore the “Heaven on Earth”. See you again!"]'::json, '["High-Quality Car","Cable Car","Live English Speaking Tour Guide","A Lunch Buffet","Entrance Fees as Itinerary","Mineral Water 2 Bottle / 1 Day / 1 Pax"]'::json, '["Optional gratuities for driver and guide","Personal expenses and additional meals"]'::json, 2300000.0, 0.0, 0.0, 0, '1 Day', NULL, 'Pickup inside of the port or Pickup outside of the port', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804725/danangtrip/tours/vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port/tour-002__vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port__p01__vmtravel-bana-hills-cable-car-in-da-nang.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804725/danangtrip/tours/vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port/tour-002__vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port__p01__vmtravel-bana-hills-cable-car-in-da-nang.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804728/danangtrip/tours/vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port/tour-002__vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port__p02__vmtravel-bana-hills.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804731/danangtrip/tours/vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port/tour-002__vmtravel-recheck-001-ba-na-hills-and-golden-bridge-tour-from-tien-sa-port__p03__vmtravel-bana-hills-tour-from-chan-may-port.jpg"]'::json, 'https://vmtravel.com/tours/ba-na-hills-and-golden-bridge-tour-from-tien-sa/', 1, 2),
    ('vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour', 'Ba Na Hills Night Tour and Sunset Golden Bridge Tour', 'tour-ba-na-hills', 'Chương trình tham quan Da Nang, Hoi An, Hue, Ba Na Hills, Son Tra với thời lượng 8 Hours. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/ba-na-hills-night-tour/', 'Tour Da Nang, Hoi An, Hue, Ba Na Hills, Son Tra, thời lượng 8 Hours, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["14:00 – Hotel Pick-up: Our driver and guide will meet you at your hotel to begin your journey to the cooler heights of Ba Na.","15:00 – Cable Car Ascent: Enjoy a scenic ride on one of the world''s longest cable car systems, rising above the lush primeval forests.","15:30 – Golden Bridge & Pagoda: Walk the famous Golden Bridge as the crowds thin out. Visit Le Jardin D’Amour Flower Garden and the tranquil Linh Ung Pagoda.","16:30 – Sunset & French Village: Capture the stunning sunset from the mountain peak before exploring the romantic French Village as the lanterns begin to glow.","18:30 – After Glow Show: Experience the magic of the After Glow Show, where light and art bring the night to life.","19:00 – Buffet Dinner: Indulge in an international buffet at Beer Plaza, featuring a wide variety of dishes and a lively atmosphere.","19:30 – Night Walk and Relaxation: Enjoy a final quiet walk to breathe in the fresh, cool mountain air before heading back.","21:00 – Return: Take the cable car down and enjoy a comfortable drive back to your hotel. Finish tour Bana Hills by Night and see you again."]'::json, '["Modern vehicle for round-trip transfer","Round-trip Cable Car ticket","Professional English-speaking guide","International Buffet dinner at Beer Plaza"]'::json, '["Personal expenses and souvenirs","Gratuities (Tips for guide/driver)","Extra drinks outside the buffet"]'::json, 1475000.0, 0.0, 0.0, 0, '8 Hours', NULL, NULL, 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804734/danangtrip/tours/vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour/tour-003__vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour__p01__vmtravel-ba-na-hills-night-tour.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804734/danangtrip/tours/vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour/tour-003__vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour__p01__vmtravel-ba-na-hills-night-tour.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804737/danangtrip/tours/vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour/tour-003__vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour__p02__vmtravel-event-at-bana-hills-by-night.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804740/danangtrip/tours/vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour/tour-003__vmtravel-central-002-ba-na-hills-night-tour-and-sunset-golden-bridge-tour__p03__vmtravel-sunset-bana-hills-da-nang.jpg"]'::json, 'https://vmtravel.com/tours/ba-na-hills-night-tour/', 1, 3),
    ('vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour', 'Ba Na Hills Tour From Da Nang 1 Day Tour: Deluxe Group Tour', 'tour-ba-na-hills', 'Chương trình tham quan Da Nang, Hoi An, Hue, Ba Na Hills, Son Tra với thời lượng 1 day. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/ba-na-hills-tour-from-da-nang/', 'Tour Da Nang, Hoi An, Hue, Ba Na Hills, Son Tra, thời lượng 1 day, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["08:00 AM Our car and guide will pick you up at your hotel in Da Nang. We will travel 40 kilometers to Ba Na Hills from the Da Nang City Center. Are you ready to conquer the road to Wonderland and explore plenty of fantastic attractions here?","09:00 AM We arrive at Ba Na Hills. Then we take a cable car to Ba Na Mountain. Sitting in a cable car, you can experience the floating sensation in the air covered with dense fog and admire the greeny natural landscape and majestic beauty of the mountains. You can visit some must","Golden Bridge The pedestrian bridge is situated at a height of 1487 meters, with a length of 150 meters (492,126 ft). Golden Bridge connected the cable car station and the flower gardens. The bridge is famous for its unique design, with the image of the two giant hands lifting th","Le Jardin D’Amour flower garden After that, we move to heaven on earth with thousands of blooming flowers that have enamored many people. The Le Jardin D''Amour flower garden is divided into nine different gardens and has hundreds of colorful and artistically shaped flowers. Along","Having a buffet lunch Recharge your battery with a hearty buffet at a restaurant in French Village. Feel free to savor the exquisite cuisine from worldwide with hundreds of mouthwatering dishes.","12:30 PM After enjoying lunch at French Village, we continued the trip to conquer the peak of Chua Mountain at 1487m. Then, you will visit Linh Ung Linh Chua Temple to bask in the purity of atmosphere and sacred space at the highest peak in Ba Na. You will find your inner peace a","Fantasy Park You continue to discover the largest indoor amusement park in Vietnam and the world. What sets Fantasy Park in Ba Na apart is its ability to offer a truly immersive and comfortable experience across various genres. With over 105 games, you can break your limits and e","French Village Next, we are off to the last spot in the itinerary, French Village. The architecture and design reflect the breath of European architecture with cobblestone streets, charming buildings, and cafes. The place recreates plenty of famous landmarks in Europe with Gothic","02:00 PM - 03:00 PM Back to the cable car down the mountain. Drop you off at your hotel in Da Nang. Finish the Ba Na Hills Tour From Da Nang. Goodbye, thank you for choosing VM Travel on the journey to explore the “Road to the Wonderland” in Da Nang City, and see you again."]'::json, '["High-Quality Minivan","Cable Car","Live English Speaking Tour Guide","A lunch buffet","Entrance fees as Itinerary","Mineral Water 2 Bottle / 1 Day / 1 Pax"]'::json, '["Optional gratuities for driver and guide","Personal expenses and additional meals","Wax Museum (100,000 vnd/pax)"]'::json, 1625000.0, 0.0, 0.0, 0, '1 day', NULL, NULL, 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804744/danangtrip/tours/vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour/tour-004__vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour__p01__vmtravel-bana-hills-big-group-tour.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804744/danangtrip/tours/vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour/tour-004__vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour__p01__vmtravel-bana-hills-big-group-tour.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804747/danangtrip/tours/vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour/tour-004__vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour__p02__vmtravel-bana-hills-in-december.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804750/danangtrip/tours/vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour/tour-004__vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour__p03__vmtravel-bana-hill-tour-from-hoi-an.jpg"]'::json, 'https://vmtravel.com/tours/ba-na-hills-tour-from-da-nang/', 1, 4),
    ('vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour', 'Ba Na Hills Tour From Hoi An - Exquisite Delight 1 Day Tour', 'tour-ba-na-hills', 'Chương trình tham quan Da Nang, Hoi An, Hue, Ba Na Hills với thời lượng 1 day. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/ba-na-hills-tour-from-hoi-an/', 'Tour Da Nang, Hoi An, Hue, Ba Na Hills, thời lượng 1 day, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["08:00 AM Our car and guide will pick you up at your hotel in Hoi An. Leave Hoi An, and we will travel the 60-kilometer to Ba Na Hills. Are you ready to conquer the road to Wonderland and explore plenty of fantastic attractions here?","09:00 AM We arrive at Ba Na Hills. Then we take a cable car to the hills. Sitting in a cable car, you can enjoy \"suspending\" in the air covered with dense fog and admire the lush natural landscape and majestic beauty of the mountains. After arriving at the Ba Na tourist area, you","Golden Bridge: The pedestrian bridge is situated at a height of 1487 meters, with a length of 150 meters (492,126 ft). Golden Bridge connected the cable car station and the flower gardens. The bridge is famous for its unique design, with the image of the two giant hands lifting t","Le Jardin D’Amour flower garden After that, we move to heaven on earth with thousands of blooming flowers that have enamored many people. The Le Jardin D''Amour flower garden is divided into nine different gardens and has hundreds of colorful and artistically shaped flowers. Conti","Having a buffet lunch Recharge your energy with a varied buffet at a restaurant in French Village. Feel free to savor the exquisite cuisine from all over the world.","12:30 P.M After having a delicious lunch in French Village, we will visit Linh Chua Linh Tu Temple to unwind, find tranquility in the sacred atmosphere, and enjoy the panoramic view of the whole area in Ba Na Hills.","Fantasy Park Continue the journey by visiting Vietnam''s largest indoor amusement park. With over 105 games, you can push your limits and embrace the excitement. Some highlights include the Free Fall 360 Ferris Wheel, Climbing the Man-Made Mountain, Super Speed Slide, The Cog Rail","French Village Next, we are off to the final spot, French Village. One of the themes within Ba Na Hills is the recreation of a French medieval village. The architecture and design are reminiscent of a European village, with cobblestone streets, charming buildings, and cafes. The","02:00 P.M Back to the cable car down the mountain. Drop you off at your hotel in Hoi An. Finish the Ba Na Hills Tour From Hoi An. Goodbye, thank you for choosing VM Travel on the journey to explore the “Road to the Wonderland”, and see you again."]'::json, '["High-Quality Minivan","Cable Car","Live English Speaking Tour Guide","A lunch buffet","Entrance fees as Itinerary","Mineral Water 2 Bottle / 1 Day / 1 Pax"]'::json, '["Optional gratuities for driver and guide","Personal expenses and additional meals","Wax Museum (100,000 vnd/pax)"]'::json, 1625000.0, 0.0, 0.0, 0, '1 day', NULL, NULL, 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804750/danangtrip/tours/vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour/tour-004__vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour__p03__vmtravel-bana-hill-tour-from-hoi-an.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804750/danangtrip/tours/vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour/tour-004__vmtravel-central-003-ba-na-hills-tour-from-da-nang-1-day-tour-deluxe-group-tour__p03__vmtravel-bana-hill-tour-from-hoi-an.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804753/danangtrip/tours/vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour/tour-005__vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour__p02__vmtravel-bana-hills-danang.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804756/danangtrip/tours/vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour/tour-005__vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour__p03__vmtravel-french-village.jpg"]'::json, 'https://vmtravel.com/tours/ba-na-hills-tour-from-hoi-an/', 1, 5),
    ('vmtravel-central-005-bana-hills-day-tour-book-1-day-tour-in-da-nang-best-trip', 'Bana Hills Day Tour - Book 1 Day Tour in Da Nang - Best Trip', 'tour-ba-na-hills', 'Chương trình tham quan Da Nang, Hoi An, Hue, Ba Na Hills, Son Tra với thời lượng 1 day. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/bana-hills-day-tour-private-tours/', 'Tour Da Nang, Hoi An, Hue, Ba Na Hills, Son Tra, thời lượng 1 day, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["Our car and guide will pick you up at your hotel in Da Nang. Then, we will travel about 20 kilometres to Ba Na Hills from the Da Nang City Center. Upon arrival at Bana, get on a cable car and admire the stunning view from the lush mountain and blue sea. After that, stroll on the","Also, you will continue to find tranquillity at Linh Ung Linh Chua Temple, lost in the ancient beauty at French Village, and have fun when you join thrilling games at Fantasy Park. Next, recharge your battery with a hearty buffet lunch at the French Village restaurant with divers","Back to the cable car down the mountain. Leave Ba Na Hills, and we will move to Han Market - the most bustling market in Da Nang. Here, you can meet friendly locals and buy souvenirs for your loved ones. After exciting experiences at the market, we will move to Son Tra Peninsula"]'::json, '["High-Quality Car","Cable Car","Live English Speaking Tour Guide","A Lunch Buffet","Entrance Fees as Itinerary","Mineral Water 2 Bottle / 1 Day / 1 Pax"]'::json, '["Optional gratuities for driver and guide","Personal expenses and additional meals"]'::json, 3150000.0, 0.0, 0.0, 0, '1 day', NULL, NULL, 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804759/danangtrip/tours/vmtravel-central-005-bana-hills-day-tour-book-1-day-tour-in-da-nang-best-trip/tour-006__vmtravel-central-005-bana-hills-day-tour-book-1-day-tour-in-da-nang-best-trip__p01__vmtravel-explore-golden-bridge.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804759/danangtrip/tours/vmtravel-central-005-bana-hills-day-tour-book-1-day-tour-in-da-nang-best-trip/tour-006__vmtravel-central-005-bana-hills-day-tour-book-1-day-tour-in-da-nang-best-trip__p01__vmtravel-explore-golden-bridge.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804756/danangtrip/tours/vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour/tour-005__vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour__p03__vmtravel-french-village.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804753/danangtrip/tours/vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour/tour-005__vmtravel-central-004-ba-na-hills-tour-from-hoi-an-exquisite-delight-1-day-tour__p02__vmtravel-bana-hills-danang.jpg"]'::json, 'https://vmtravel.com/tours/bana-hills-day-tour-private-tours/', 1, 6),
    ('recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel', 'Cham Island Sightseeing & Snorkeling Tour', 'tour-bien-dao', 'Chương trình tham quan Da Nang, Hoi An, Hue, Cu Lao Cham với thời lượng 6 hours. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://venusvietnamtravel.com/cham-island-sightseeing-and-snorkeling-tour/', 'Tour Da Nang, Hoi An, Hue, Cu Lao Cham, thời lượng 6 hours, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["08:00–14:00 Pick-up & Join the tour","Pick-up Driver will pick you up at your hotel and transfer to Cua Dai harbour.","Cham Island Relaxing in fresh cool wind , you will enjoy the beautiful landscape on a speed boat to Cham Island. Visit to he Marine Protected Area, The Boat Shelter, Hai Tang pagoda, Traditional fishing Village","Swimming and snorkeling You will have about 30 minute to swim and snorkel","Lunch time Staying at Bai Ong ecological zone or Bai Chong beach, swimming, taking time to enjoy a sea food lunch.","14:00–14:30 Come back to your hotel","Drop off Seeing you off at your hotel and finish your trip"]'::json, '["Transportation","English-speaking tour guide","Entrance fees.","Meals according to the itinerary.","Travel insurance.","Mineral water: 500ml/pax"]'::json, '["Motoboat jetski, Banana Boat, Fishing.","Drinks.","Tips & gratuities for guides and drivers"]'::json, 765500.0, 0.0, 0.0, 0, '6 hours', NULL, 'Depart from Hoi An / Da Nang / Hue Depart from Ha Noi Depart from Ho Chi Minh Pakage T', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804761/danangtrip/tours/recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel/tour-007__recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel__p01__venus-cu-lao-cham-2-e1700123421497.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804761/danangtrip/tours/recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel/tour-007__recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel__p01__venus-cu-lao-cham-2-e1700123421497.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804764/danangtrip/tours/recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel/tour-007__recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel__p02__pexels-5116361.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804767/danangtrip/tours/recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel/tour-007__recrawl-022-venusvietnamtravel-cham-island-sightseeing-snorkeling-tour-venustravel__p03__pexels-27506369.jpg"]'::json, 'https://venusvietnamtravel.com/cham-island-sightseeing-and-snorkeling-tour/', 1, 7),
    ('vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang', 'Cham Island Snorkeling Tour from Hoi An or Da Nang', 'tour-bien-dao', 'Chương trình tham quan Da Nang, Hoi An, Hue, Cu Lao Cham với thời lượng 6 Hours. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/cham-island-snorkeling-tour/', 'Tour Da Nang, Hoi An, Hue, Cu Lao Cham, thời lượng 6 Hours, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["07:30 – 08:00 AM: We’ll begin your day with a comfortable pickup from your hotel in Hoi An or Da Nang. Our friendly tour guide will greet you and escort you to Cua Dai Port in Hoi An, where your boat journey begins.","08:30 AM: Hop on a high-speed boat and enjoy the fresh breeze as we cruise through the clear waters of the East Sea. The ride to Cham Island takes about 25–30 minutes, giving you beautiful views of the coastline and open sea.","09:00 AM: we head to Bai Lang Village, the main village on Cham Island. Here, you can explore local life, visit the island market, and see historical spots such as Hai Tang Pagoda, Tan Hiep Market and the Ancient Well. It’s a great chance to learn about the culture and history of","We’ll anchor at one of the best snorkelling spots around the island. Here, you’ll put on your snorkelling gear and dive into the water to explore the colourful marine life. Swim alongside tropical fish, admire coral reefs, and soak in the peace of the underwater world.","12:00 PM: Enjoy a Seafood Lunch at a Beachside Restaurant, We’ll move to Bai Chong Beach, where a tasty seafood lunch is served at a local beachside restaurant. Vegetarian meals are available on request. Enjoy your meal while listening to the sound of the waves and the fresh sea","13:00 PM: Free Time to Swim or Relax, after lunch, you’ll have time to relax on the beach, swim in the crystal-clear water, or simply unwind in the shade. Take in the beautiful scenery and enjoy the peaceful island atmosphere.","13:30 PM: Hop back on the speedboat for a smooth ride back to Cua Dai Port.","14:30 – 15:00 PM: Drop-off at Your Hotel, Our driver will take you back to your hotel in Hoi An or Da Nang. You’ll arrive in the afternoon, refreshed and full of great memories from your Cham Island trip."]'::json, '["Hotel pickup and drop-off (Hoi An or Da Nang city centre)","Round-trip speedboat to Cham Island","English-speaking guide","Entrance fees to Cham Island","Snorkelling equipment (mask, snorkel, life jacket)","Seafood lunch (vegetarian option available)","Bottled water"]'::json, '["Personal expenses","Towels and swimwear","Drinks during lunch","Tips for guide and boat crew (optional)"]'::json, 750000.0, 0.0, 0.0, 0, '6 Hours', NULL, 'pickup, boat transfers, snorkelling gear, entrance fees, and lunch, so all you need to', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804770/danangtrip/tours/vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang/tour-008__vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang__p01__vmtravel-snockerling-in-cham-island.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804770/danangtrip/tours/vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang/tour-008__vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang__p01__vmtravel-snockerling-in-cham-island.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804773/danangtrip/tours/vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang/tour-008__vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang__p02__vmtravel-cham-island-tour-from-da-nang.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804777/danangtrip/tours/vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang/tour-008__vmtravel-central-006-cham-island-snorkeling-tour-from-hoi-an-or-da-nang__p03__vmtravel-cu-lao-cham.jpg"]'::json, 'https://vmtravel.com/tours/cham-island-snorkeling-tour/', 1, 8),
    ('vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel', 'Da Nang City Tour - Deluxe Group Tour', 'tour-trong-ngay', 'Chương trình tham quan Da Nang, Hoi An, Hue, Son Tra với thời lượng 6 Hours. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/da-nang-city-tour-deluxe-group/', 'Tour Da Nang, Hoi An, Hue, Son Tra, thời lượng 6 Hours, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["At about 08:45 - 09:15 a.m: Our team will pick you up at your Da Nang City Center hotel.","The first place to visit is the Marble Mountain . It is a group of five limestone mountains located about eight kilometers south of Da Nang. The mountain is well-known for its hidden caves, shrines, and pagodas.","After that, visit the Non Nuoc Stone Carving Village at the foot of Marble Mountain. Here, you can admire the stone sculptures made under the incredibly skillful hands of the local artists.","11:00 a.m: Continue visiting Linh Ung Bai But Pagoda , located at Son Tra Peninsula, and admire the biggest Avalokitesvara Bodhisattva Statue of Viet Nam.","12:15 p.m: Transfer back to city center by visit Han Market . Here, you can observe how Danang’s people sell the local products and buy lovely local souvenirs.","12:45 p.m: Then, have a delicious lunch with traditional Vietnamese dishes in the restaurant.","01:30 p.m: Later, our team will say good bye at your hotel. Finish the Danang City Tour"]'::json, '["High-Quality Minivan","Live English Speaking Tour Guide","Local Lunch with Vietnam Cuisine","Entrance fees as Itinerary","Mineral water on coach"]'::json, '["Optional gratuities for driver and guide","Personal expenses and additional meals","Pick up from your hotel outside the city center"]'::json, 800000.0, 0.0, 0.0, 0, '6 Hours', NULL, NULL, 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804780/danangtrip/tours/vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel/tour-009__vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel__p01__vmtravel-danang-tour.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804780/danangtrip/tours/vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel/tour-009__vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel__p01__vmtravel-danang-tour.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804783/danangtrip/tours/vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel/tour-009__vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel__p02__vmtravel-marble-mountains.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804786/danangtrip/tours/vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel/tour-009__vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel__p03__vmtravel-my-khe-beach.jpg"]'::json, 'https://vmtravel.com/tours/da-nang-city-tour-deluxe-group/', 1, 9),
    ('vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping', 'Da Nang City Tour From Tien Sa Port - Explore and Shopping', 'tour-trong-ngay', 'Chương trình tham quan Da Nang, Hoi An, Hue, Son Tra với thời lượng 1 Day. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/da-nang-city-tour-from-tien-sa-port/', 'Tour Da Nang, Hoi An, Hue, Son Tra, thời lượng 1 Day, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["Our driver and guide will pick you up at Tien Sa Port with a welcome board with your name. You can choose Pickup inside of the port or Pickup outside of the port. Then, transfer you to Da Nang City","Begin your day with an exploration trip to Marble Mountain - a group of five limestone hills about eight kilometers south of Da Nang. Here, you can admire the hidden caves, temples, and pagodas.","Next, you will move to the foot of the mountain to visit Non Nuoc Stone Craving Village. You can satisfy your eyes with the stone sculptures made under the incredibly skillful hands of the local artisans and buy some souvenirs.","Continue the tour by visiting the Cham Sculpture Museum to admire the invaluable artifacts of the Cham people - an ethnic group that once thrived in Central southern Vietnam. Later, have lunch in a local restaurant to enjoy Danang''s specialties and Vietnamese cuisine. Take a shor","The tour will continue by visiting Han Market - the most bustling market in Da Nang. Here, meet and talk with friendly locals, observe the daily locals’ activities, and buy Danang local souvenirs for your loved ones.","After exciting experiences at the market, we will move to Son Tra Peninsula to learn about the local spiritual lives at Linh Ung Bai But Pagoda - the largest pagoda among the three Linh Ung Pagoda in Danang. From the mountain, you can see the whole city in your eyes with panorami","Finish the Da Nang City Tour From Tien Sa Port ! Goodbye, and thank you for choosing VM Travel to explore the most livable city in Vietnam. See you again!"]'::json, '["High-Quality Transport","Live English Speaking Tour Guide","Local Lunch with Vietnam Cuisine","Entrance fees as Itinerary","Mineral Water 2 Bottles / 1 day / 1 pax"]'::json, '["Optional gratuities for driver and guide","Personal expenses and additional meals"]'::json, 2050000.0, 0.0, 0.0, 0, '1 Day', NULL, 'Pickup inside of the port or Pickup outside of the port', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804789/danangtrip/tours/vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping/tour-010__vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping__p01__vmtravel-da-nang-city-tour-1.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804789/danangtrip/tours/vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping/tour-010__vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping__p01__vmtravel-da-nang-city-tour-1.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804792/danangtrip/tours/vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping/tour-010__vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping__p02__vmtravel-da-nang-full-day-trip.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804795/danangtrip/tours/vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping/tour-010__vmtravel-recheck-002-da-nang-city-tour-from-tien-sa-port-explore-and-shopping__p03__vmtravel-cham-mesurm.jpg"]'::json, 'https://vmtravel.com/tours/da-nang-city-tour-from-tien-sa-port/', 1, 10),
    ('vmtravel-central-008-da-nang-day-tour-private-tour-highlight-full-day-tour', 'Da Nang Day Tour - Private Tour | Highlight Full Day Tour', 'tour-trong-ngay', 'Chương trình tham quan Da Nang, Hoi An, Hue, Son Tra với thời lượng 1 Day. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/da-nang-day-tour-private-tour/', 'Tour Da Nang, Hoi An, Hue, Son Tra, thời lượng 1 Day, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["Our driver and guide will pick you up at your Da Nang City Center hotel. Begin your day with an exploration trip to Marble Mountain - a group of five limestone hills about eight kilometers south of Da Nang. Here, you can admire the hidden caves, temples, and pagodas. Next, you wi","Continue the tour by visiting the Cham Sculpture Museum to admire the invaluable artifacts of the Cham people - an ethnic group that once thrived in Central southern Vietnam. Later, have lunch in a local restaurant to savor Danang''s specialties and Vietnamese cuisine. Take a shor","The Tour will continue by visiting Han Market - the most bustling market in the city. Here, meet and talk with friendly locals, observe the daily locals’ activities, and buy authentic Danang souvenirs for your loved ones. After exciting experiences at the market, we will move to","Leaving Son Tra Peninsula, we will go to My Khe Beach - one of the most beautiful beaches in Vietnam. Here, you have free time to snap photos of blue beaches and golden sunshine. Later, you will be dropped off at your hotel."]'::json, '["High-Quality Transport","Live English Speaking Tour Guide","Local Lunch with Vietnam Cuisine","Entrance fees as Itinerary","Mineral Water 2 Bottles / 1 day / 1 pax"]'::json, '["Optional gratuities for driver and guide","Personal expenses and additional meals","Pick up from your hotel outside the city center"]'::json, 3450000.0, 0.0, 0.0, 0, '1 Day', NULL, NULL, 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804798/danangtrip/tours/vmtravel-central-008-da-nang-day-tour-private-tour-highlight-full-day-tour/tour-011__vmtravel-central-008-da-nang-day-tour-private-tour-highlight-full-day-tour__p01__vmtravel-da-nang-city-tour.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804798/danangtrip/tours/vmtravel-central-008-da-nang-day-tour-private-tour-highlight-full-day-tour/tour-011__vmtravel-central-008-da-nang-day-tour-private-tour-highlight-full-day-tour__p01__vmtravel-da-nang-city-tour.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804783/danangtrip/tours/vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel/tour-009__vmtravel-central-007-da-nang-city-tour-deluxe-group-tour-vm-travel__p02__vmtravel-marble-mountains.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804801/danangtrip/tours/vmtravel-central-008-da-nang-day-tour-private-tour-highlight-full-day-tour/tour-011__vmtravel-central-008-da-nang-day-tour-private-tour-highlight-full-day-tour__p03__vmtravel-linh-ung-pagoda-1.jpg"]'::json, 'https://vmtravel.com/tours/da-nang-day-tour-private-tour/', 1, 11),
    ('vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities', 'Da Nang Hoi An Full Day Tour - See the Best of Both Cities', 'tour-hoi-an', 'Chương trình tham quan Da Nang, Hoi An, Hue, Son Tra với thời lượng 1 Day. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/da-nang-hoi-an-full-day-tour/', 'Tour Da Nang, Hoi An, Hue, Son Tra, thời lượng 1 Day, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["At 9:00 AM: Our tour guide and driver will pick you up from your hotel in Da Nang City Center to begin the journey to explore two charming cities of Central Vietnam.","Begin your journey with a visit to Marble Mountain , a cluster of limestone hills. Climb to the top of Thuy Son Mountain for a stunning view, explore ancient caves, and visit the peaceful pagodas scattered throughout the site.","Next, continue to visit Linh Ung Pagoda on the Son Tra Peninsula. Marvel at the majestic Lady Buddha statue overlooking the South China Sea and enjoy panoramic views of Da Nang’s coastline.","Continue the trip by exploring Han Market , one of the oldest and most vibrant markets in Da Nang City. Come here, you can learn more about the daily local life and go shopping in the market.","Afterward, take a break and enjoy a traditional Vietnamese lunch at a local restaurant.","After lunch, transfer to Cam Thanh Coconut Forest , you will have the chance to take a basket boat to explore the coconut forest and watch local people perform and have fun with a basketboat. Experience and learn about the culture of locals and watch fishermen catch fish with net","Continue to head to Hoi An Ancient Town . Stroll through its charming streets, explore the well-preserved historic buildings, visit the iconic Japanese Covered Bridge, and discover Hoi An’s rich cultural heritage. You’ll also have time to visit temples, old merchant houses, Phuc","Enjoy a romantic dinner at a local restaurant in Hoi An Old Town.","At 7:30PM: After a day of exploring, leave Hoi An and back to your hotel in Da Nang."]'::json, '["Hotel pick-up and drop-off","Boat on Hoai River and lantern","English-speaking guide","Entrance fee as itinerary","Basket boat at coconut forest","Lunch at a local restaurant","Air-conditioned transportation","Bottled water"]'::json, '["Personal expenses and additional meals","Tips for the guide and driver","Travel insurance"]'::json, 1300000.0, 0.0, 0.0, 0, '1 Day', NULL, NULL, 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804804/danangtrip/tours/vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities/tour-012__vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities__p01__vmtravel-da-nang-and-hoi-an-city-tour.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804804/danangtrip/tours/vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities/tour-012__vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities__p01__vmtravel-da-nang-and-hoi-an-city-tour.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804808/danangtrip/tours/vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities/tour-012__vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities__p02__vmtravel-da-nang-city-tour-1.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804811/danangtrip/tours/vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities/tour-012__vmtravel-central-010-da-nang-hoi-an-full-day-tour-see-the-best-of-both-cities__p03__vmtravel-hoian-lantern-festival.jpg"]'::json, 'https://vmtravel.com/tours/da-nang-hoi-an-full-day-tour/', 1, 12),
    ('vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass', 'Da Nang to Hue Day Trip by Heritage Train via Hai Van Pass', 'tour-train-hue', 'Chương trình tham quan Da Nang, Hoi An, Hue với thời lượng 9 Hours. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/da-nang-to-hue-day-trip-by-heritage-train/', 'Tour Da Nang, Hoi An, Hue, thời lượng 9 Hours, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["Our professional guide and driver will pick you up from your hotel in Da Nang. We head to the Da Nang Railway Station to begin your nostalgic adventure.","Board the Heritage Train for a breathtaking ride. This is the highlight of the trip, where you can admire the majestic Hai Van Pass and the sparkling waters of Lang Co Bay from a unique railway perspective.","The train arrives at Lang Co Station. Your private vehicle will be waiting to take you directly to Hue. We spend the morning exploring the Hue Imperial Citadel , the historic seat of the Nguyen Dynasty, featuring the Forbidden Purple City and Royal Temples.","Savor a delicious lunch at a hand-picked local restaurant, featuring authentic Hue specialties. Afterward, treat yourself to a traditional herbal foot soak, a royal wellness method used to rejuvenate your energy.","Experience Footbath in local restaurant","In the afternoon, we visit the iconic Thien Mu Pagoda , the oldest religious site in Hue overlooking the Perfume River. We then continue to the Khai Dinh Tomb , a masterpiece of architecture blending Eastern and Western styles with intricate porcelain mosaics.","Say goodbye to the ancient capital as we board our private vehicle for the return journey to Da Nang via the modern Hai Van Tunnel.","Arrive back at your hotel in Da Nang. Your Da Nang to Hue Day trip by heritage train concludes with unforgettable memories."]'::json, '["Train ticket Da Nang to Lang Co Station (1 way)","Minivan with A/C","English speaking guide","Entrance fees","Lunch","Footbath","Water and tissues","Yes, the tour is all-inclusive of the heritage train ticket from Da Nang to Hue, all entrance fees to historical sites, lunch, and transportation."]'::json, '["Personal expenses, beverages during meals.","Tips for the tour guide and driver (optional).","Any additional costs not included in the program.","Extra fee applicable on public holidays in Vietnam."]'::json, 1625000.0, 0.0, 0.0, 0, '9 Hours', NULL, 'Depart for Da Nang Say goodbye to the ancient capital as we board our private vehicle', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804814/danangtrip/tours/vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass/tour-013__vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass__p02__vmtravel-hue-day-trip-from-chan-may-port.webp', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804814/danangtrip/tours/vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass/tour-013__vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass__p02__vmtravel-hue-day-trip-from-chan-may-port.webp","https://res.cloudinary.com/dmukxquza/image/upload/v1780804817/danangtrip/tours/vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass/tour-013__vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass__p03__vmtravel-train-in-vietnam.jpg"]'::json, 'https://vmtravel.com/tours/da-nang-to-hue-day-trip-by-heritage-train/', 1, 13),
    ('vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour', 'Day Trip From Da Nang To Hoi An - Deluxe Group Tour', 'tour-hoi-an', 'Chương trình tham quan Da Nang, Hoi An, Hue với thời lượng 6 Hours. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/day-trip-from-da-nang-to-hoi-an/', 'Tour Da Nang, Hoi An, Hue, thời lượng 6 Hours, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["At 1:45 - 2:00 pm: Our driver and guide will pick you up and transfer you to Hoi An.","At 3:00 pm: Upon arrival in Cam Thanh Coconut Forest - a beautiful water coconut palm forest about 5km southeast of the Hoi An Old Town. You will get in a basket boat to explore the coconut forest and learn about the daily activities of local fishermen and the village’s history.","At 4:00 pm: Continue the day trip by visiting Hoi An Old Town - a bustling international trading port from the 16th to 17th century. Your tour guide will take you to the Assembly Halls, Old Houses, and other cultural constructions to learn about the unique ancient architecture, l","06:00 p.m: Get in a boat to cruise on the Hoai River and admire the charming town from a different perspective. Enjoy the sparkling night while dropping flower lanterns into the clam water. Lighting a flower lantern is like wishing good luck and peace, bringing health and fortune","06:30 p.m: Fill your day with Hoi An specialties in a Vietnamese restaurant.","07:30 p.m: Leave Hoi An, come back to Da Nang City, and say goodbye at your hotel in Danang.","Finish the Hoi An Day Trip from Da Nang - Small Group Tour. Goodbye, and thank you for choosing VM Travel to explore timeless beauty at Hoi An Ancient Town. See you again!"]'::json, '["High-Quality Minivan","Live English Speaking Tour Guide","Local Dinner with Hoi An/ Vietnamese Cuisine","Basket boat in Coconut Forest","Boat on Hoai River (If requested)","Mineral Water"]'::json, '["Optional gratuities for driver and guide","Personal expenses and additional meals","Pick up from your hotel outside the city center"]'::json, 900000.0, 0.0, 0.0, 0, '6 Hours', NULL, NULL, 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804820/danangtrip/tours/vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour/tour-014__vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour__p01__vmtravel-tour-coconut.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804820/danangtrip/tours/vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour/tour-014__vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour__p01__vmtravel-tour-coconut.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804823/danangtrip/tours/vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour/tour-014__vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour__p02__vmtravel-hoian-in-vietnam.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804826/danangtrip/tours/vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour/tour-014__vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour__p03__vmtravel-cam-thanh-coconut-village.jpg"]'::json, 'https://vmtravel.com/tours/day-trip-from-da-nang-to-hoi-an/', 1, 14),
    ('vmtravel-central-013-day-trip-to-hoi-an-from-da-nang-private-tour-vm-travel', 'Day Trip To Hoi An From Da Nang - Private Tour', 'tour-hoi-an', 'Chương trình tham quan Da Nang, Hoi An, Hue với thời lượng 1 day. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/day-trip-to-hoi-an-from-da-nang/', 'Tour Da Nang, Hoi An, Hue, thời lượng 1 day, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["Our car and guide will pick you up at your hotel in Da Nang and then transfer you to Hoi An. Hoi An Day Trip starts with Cam Thanh Coconut Village - about 5km southeast of the Hoi An Old Town. You will experience a basket boat ride around the coconut forest and learn about the da","Exploring Hoi An Ancient Town - one of the most charming towns in the world. Our tour guide will take you to the Assembly Halls, Old Houses, and other historical sites to learn about the unique ancient architecture and local lifestyles. Then, you have free time to wander around t"]'::json, '["High-Quality Minivan","Live English Speaking Tour Guide","Local Lunch with Vietnam Cuisine","Entrance fees as Itinerary","Boat trip on Hoai River","Mineral Water 2 Bottles / 1 day / 1 pax"]'::json, '["Optional gratuities for driver and guide","Personal expenses and additional meals","Pick up from your hotel outside the city center"]'::json, 2750000.0, 0.0, 0.0, 0, '1 day', NULL, NULL, 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804829/danangtrip/tours/vmtravel-central-013-day-trip-to-hoi-an-from-da-nang-private-tour-vm-travel/tour-015__vmtravel-central-013-day-trip-to-hoi-an-from-da-nang-private-tour-vm-travel__p01__vmtravel-visit-hoian.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804829/danangtrip/tours/vmtravel-central-013-day-trip-to-hoi-an-from-da-nang-private-tour-vm-travel/tour-015__vmtravel-central-013-day-trip-to-hoi-an-from-da-nang-private-tour-vm-travel__p01__vmtravel-visit-hoian.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804820/danangtrip/tours/vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour/tour-014__vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour__p01__vmtravel-tour-coconut.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804832/danangtrip/tours/vmtravel-central-013-day-trip-to-hoi-an-from-da-nang-private-tour-vm-travel/tour-015__vmtravel-central-013-day-trip-to-hoi-an-from-da-nang-private-tour-vm-travel__p03__vmtravel-coffee-hoian.jpg"]'::json, 'https://vmtravel.com/tours/day-trip-to-hoi-an-from-da-nang/', 1, 15),
    ('vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang', 'Highlight The 4 Days Deluxe Golf Tour In Da Nang', 'tour-golf', 'Chương trình tham quan Da Nang, Hoi An, Hue, Ba Na Hills với thời lượng 4 Days. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/4-days-deluxe-golf-tour-in-da-nang/', 'Tour Da Nang, Hoi An, Hue, Ba Na Hills, thời lượng 4 Days, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["Welcome to Danang! Upon arrival at Danang International Airport, you will be greeted by our representative and transferred to your hotel. Check-in hotel and relax.","Enjoy a welcome dinner featuring local specialties at a renowned restaurant.","After breakfast, depart for BRG Danang Golf Course , a championship course designed by Greg Norman. The course demands accuracy and precision, with undulating fairways, strategically placed bunkers, and firm, fast greens. Immerse yourself in the stunning coastal landscape, with r","Have lunch and enjoy world-class facilities, including a clubhouse with fine dining, a pro shop, and practice facilities.","Return to the hotel and you might explore the vibrant city of Da Nang at night by taking a luxury cruise on the Han river, enjoy your dinner and watch the city’s brilliant lights.","Enjoy a delicious breakfast before heading to Bana Hills Golf Club , nestled in the enchanting Ba Na Hills mountain resort. This 18-hole championship course offers stunning panoramic views of the surrounding valleys and mountains, creating a truly unforgettable atmosphere.","Enjoy your lunch and relax at the clubhouse, which offers a luxurious and relaxing environment to unwind after your round. You can stroll around the golf course and shop for golf equipment here.","Return to your hotel and take a cruise Han River, enjoy dinner and admire the bustling city and brilliant lights.","Enjoy a leisurely breakfast before checking out the hotel. Transfer to the airport for your departure flight. End of the tour."]'::json, '["Enthusiastic, friendly, experienced caddies at each golf course","Shared buggy at each golf course","All airport and golf course transfers by private car","Hotel 4 stars with breakfast included","Meals as mention","2 bottles of water/golfer/day tour on transfer (500ml/bottle)","01 bottle of water/pax/way of airport transfer (500ml/bottle)","Local knowledge, suggestions, and support throughout the trip","24/7 golf hotline staffed by knowledgeable service personnel","Professional English speaking tour guide for sightseeing tour"]'::json, '["All airfares, visa","Personal items, drinks, and gratuities","International bank fund transfer fees","Other things that are not mentioned in the inclusions list"]'::json, 10625000.0, 0.0, 0.0, 0, '4 Days', NULL, 'depart for BRG Danang Golf Course , a championship course designed by Greg Norman', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804835/danangtrip/tours/vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang/tour-016__vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang__p01__vmtravel-da-nang-golf-courses.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804835/danangtrip/tours/vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang/tour-016__vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang__p01__vmtravel-da-nang-golf-courses.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804838/danangtrip/tours/vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang/tour-016__vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang__p02__vmtravel-brg-danang-golf-course.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804842/danangtrip/tours/vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang/tour-016__vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang__p03__vmtravel-vietnam-golf-tour.jpg"]'::json, 'https://vmtravel.com/tours/4-days-deluxe-golf-tour-in-da-nang/', 4, 16),
    ('vmtravel-recheck-003-hoi-an-day-tour-from-tien-sa-port-hoi-an-shore-excursions', 'Hoi An Day Tour from Tien Sa Port - Hoi An Shore Excursions', 'tour-hoi-an', 'Chương trình tham quan Da Nang, Hoi An, Hue với thời lượng 1 Day. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/hoi-an-day-tour-from-tien-sa-port/', 'Tour Da Nang, Hoi An, Hue, thời lượng 1 Day, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["Our driver and guide will pick you up at Tien Sa Port with a welcome board with your name. You can choose Pickup inside of the port or Pickup outside of the port. Then, transfer you to Hoi An City. Arrive in Cam Thanh Coconut Forest - a beautiful water coconut palm forest about 5","Next, enjoy Hoi An food in a local restaurant. Continue the day trip by visiting Hoi An Old Town - a bustling international trading port from the 16th to 17th century. Your tour guide will take you to the Assembly Halls, Old Houses, and other cultural and historical constructions","Finish Coconut Forest and Hoi An Town from Tien Sa Port. Goodbye, and thank you for choosing VM Travel to explore timeless beauty at Hoi An Ancient Town. See you again!"]'::json, '["High-Quality Minivan","Live English Speaking Tour Guide","Local Dinner with Hoi An/ Vietnamese Cuisine","Entrance fees as Itinerary","Mineral Water 2 Bottle / 1 Day / 1 Pax"]'::json, '["Optional gratuities for driver and guide","Personal expenses and additional meals","Pick up from your hotel outside the city center"]'::json, 1500000.0, 0.0, 0.0, 0, '1 Day', NULL, 'Pickup inside of the port or Pickup outside of the port', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804845/danangtrip/tours/vmtravel-recheck-003-hoi-an-day-tour-from-tien-sa-port-hoi-an-shore-excursions/tour-017__vmtravel-recheck-003-hoi-an-day-tour-from-tien-sa-port-hoi-an-shore-excursions__p01__vmtravel-hoi-an-full-day-tour.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804845/danangtrip/tours/vmtravel-recheck-003-hoi-an-day-tour-from-tien-sa-port-hoi-an-shore-excursions/tour-017__vmtravel-recheck-003-hoi-an-day-tour-from-tien-sa-port-hoi-an-shore-excursions__p01__vmtravel-hoi-an-full-day-tour.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804826/danangtrip/tours/vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour/tour-014__vmtravel-central-012-day-trip-from-da-nang-to-hoi-an-deluxe-group-tour__p03__vmtravel-cam-thanh-coconut-village.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804848/danangtrip/tours/vmtravel-recheck-003-hoi-an-day-tour-from-tien-sa-port-hoi-an-shore-excursions/tour-017__vmtravel-recheck-003-hoi-an-day-tour-from-tien-sa-port-hoi-an-shore-excursions__p03__vmtravel-best-time-visit-hoian-coconut.jpg"]'::json, 'https://vmtravel.com/tours/hoi-an-day-tour-from-tien-sa-port/', 1, 17),
    ('vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class', 'Hue Bicycle Tour: Organic Farm Visit & Local Cooking Class', 'tour-am-thuc', 'Chương trình tham quan Da Nang, Hoi An, Hue, My Son với thời lượng 8 Hours. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/hue-bicycle-tour/', 'Tour Da Nang, Hoi An, Hue, My Son, thời lượng 8 Hours, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["08:30 AM – Doorstep Welcome: Begin your journey with a private pick-up from your Hue hotel. We’ll leave the city bustle behind for the emerald landscapes of La Chu Village.","The Scent of Lotus: Arrive at a traditional garden house where a chilled glass of local lotus tea awaits—a refreshing prelude to your rural immersion.","Heritage on Two Wheels: Glide through quiet, tree-lined lanes on a bicycle. Our path leads to a centuries-old pagoda, bustling local markets, and ornate family temples that hold the village’s history.","Organic Roots at Madam Thu Farm: Step into the first organic sanctuary of the village. Roll up your sleeves for a hands-on farming session—harvesting seasonal greens and learning the art of traditional cultivation.","The Garden Kitchen: Under the shade of pomelo trees, join our local hosts to craft authentic Hue delicacies using your freshly harvested ingredients.","Countryside Banquet: Enjoy a private, home-cooked lunch served in the heart of the garden, where every bite tells a story of the land.","Botanical Bliss: Before departing, indulge in a therapeutic herbal foot bath. Let the warmth of lemongrass and ginger, picked straight from the garden, soothe your senses.","02:00 PM – Homeward Bound: We bid farewell to La Chu and escort you back to your hotel, carrying the peaceful rhythm of the village with you."]'::json, '["Transportation (car and bicycle)","Local guide (English / French speaking)","Entrance fees","Lunch","Cooking class with a local chef","Herbal foot bath"]'::json, '["Personal expenses","Services not mentioned above"]'::json, 1500000.0, 0.0, 0.0, 0, '8 Hours', NULL, 'departing, indulge in a therapeutic herbal foot bath', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804851/danangtrip/tours/vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class/tour-018__vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class__p01__vmtravel-hue-cycling-tour.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804851/danangtrip/tours/vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class/tour-018__vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class__p01__vmtravel-hue-cycling-tour.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804854/danangtrip/tours/vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class/tour-018__vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class__p02__vmtravel-hue-eco-tour-farm.webp","https://res.cloudinary.com/dmukxquza/image/upload/v1780804857/danangtrip/tours/vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class/tour-018__vmtravel-central-014-hue-bicycle-tour-organic-farm-visit-local-cooking-class__p03__vmtravel-hue-bicycle-tour.webp"]'::json, 'https://vmtravel.com/tours/hue-bicycle-tour/', 1, 18),
    ('vmtravel-central-016-hue-cooking-class-tour-from-market-to-table', 'Hue Cooking Class Tour - From Market to Table', 'tour-am-thuc', 'Chương trình tham quan Da Nang, Hoi An, Hue với thời lượng 6 hours. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/hue-cooking-class-tour/', 'Tour Da Nang, Hoi An, Hue, thời lượng 6 hours, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["About 8:30 AM: We will pick you up at your hotel by a cyclo and transfer you to a local market - Dong Ba Market.","Arrive at the bustling market. We will take you on a tour, and introduce you to the various ingredients that are essential to Hue cuisine. You''ll learn about local vegetables, herbs, spices, and other ingredients, and you may have the opportunity to purchase fresh items for the c","After the market tour, you’ll be driven to a local restaurant and join a “cooking class”. Under the guidance of the chef, you’ll chop, marinate, and cook the ingredients, following traditional methods. The chef will provide tips and tricks, and you''ll get to ask questions as you","Once the cooking is done, it’s time to sit down and enjoy the meal you’ve prepared and our chief will be able to give her feedback on your chef skills. This is a great opportunity to taste the rich flavors of Hue cuisine. Then you will have a great time relaxing by steeping your"]'::json, '["Transfer by Cyclo","Cooking class with the chef","Lunch at the restaurant","Footbath with medicinal herbs"]'::json, '["Beverage in Meal"]'::json, 1125000.0, 0.0, 0.0, 0, '6 hours', NULL, NULL, 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804860/danangtrip/tours/vmtravel-central-016-hue-cooking-class-tour-from-market-to-table/tour-019__vmtravel-central-016-hue-cooking-class-tour-from-market-to-table__p01__vmtravel-hue-cooking-class.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804860/danangtrip/tours/vmtravel-central-016-hue-cooking-class-tour-from-market-to-table/tour-019__vmtravel-central-016-hue-cooking-class-tour-from-market-to-table__p01__vmtravel-hue-cooking-class.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804863/danangtrip/tours/vmtravel-central-016-hue-cooking-class-tour-from-market-to-table/tour-019__vmtravel-central-016-hue-cooking-class-tour-from-market-to-table__p02__vmtravel-cooking-class-at-madam-thu.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804866/danangtrip/tours/vmtravel-central-016-hue-cooking-class-tour-from-market-to-table/tour-019__vmtravel-central-016-hue-cooking-class-tour-from-market-to-table__p03__vmtravel-cyclo-in-hue.jpg"]'::json, 'https://vmtravel.com/tours/hue-cooking-class-tour/', 1, 19),
    ('vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour', 'Hue DMZ Tour - Unveiling History on Captivating Tour', 'tour-hue', 'Chương trình tham quan Da Nang, Hoi An, Hue với thời lượng 1 Day. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/hue-dmz-tour-deluxe-group-tour/', 'Tour Da Nang, Hoi An, Hue, thời lượng 1 Day, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["07:30 A.M: Our guide and car will pick you up at your hotel or stay at Hue City and transfer you to the DMZ in Quang Tri. Are you ready to step on the journey to explore glorious Vietnam''s history? VM Travel will accompany you on this history tour.","9:00 A.M: Arrived in Quang Tri. On Highway 9, you have a chance to see Rock Pile Hill. It is one of the US military bases and was used as a watchtower to observe the activities of the Vietnam People’s Army in the DMZ from 1966 to 1968.","Visit Dakrong Bridge, which is one of the main branches of the Ho Chi Minh Trail. A hedging bridge surrounded by the majestic natural scenery with mountains and forests. The bridge was an important transport route for the Southern battlefield during the war.","Our car continue to take you to Quang Tri Ancient Citadel. This citadel is famous for being the site of fierce battles lasting 81 days. Nowadays, the Quang Tri Ancient Citadel is the place that marks the immortal victories of the Quang Tri army and people and become an emblem of","Continue visiting Khe Sanh Combat Base, a US military base. The combat base was the site of several famous battles between 1967 and 1968. Especially during the Mau Than Battle, the North Vietnamese Army encircled and attacked a large group of US Marines.","Return to Highway 1 for lunch at a local restaurant in Dong Ha town. Take a short break before continuing the trip to other historical sites in the afternoon.","2:00 P.M: You continue the history journey to visit the Hien Luong Bridge and the Ben Hai River, a symbol of Vietnam’s partition. After the Geneva Agreement, they used the 17th parallel to divide Vietnam into northern and southern sections, each with its administration. The bridg","3:00 P.M: Visit Vinh Moc tunnels, the most highlight part of the history tour. Vinh Moc tunnels are famous as an underground network constructed by locals to avoid bombings during the American War. It is a world of living and fighting underground, completely isolated from the out","4:30 P.M: Finish Hue DMZ Tour and come back to Hue City. Goodbye, thank you for choosing VM Travel, and see you again!"]'::json, '["High-Quality Minivan","Live English Speaking Tour Guide","Local Lunch with Vietnam Cuisine","Entrance fees as Itinerary","Mineral Water 2 Bottle / 1 Day / 1 Pax"]'::json, '["Personal expenses and additional meals","Pick up from your hotel/stay outside the center of Hue","Optional gratuities for driver and guide"]'::json, 1250000.0, 0.0, 0.0, 0, '1 Day', NULL, 'depart from Da Nang or Hoi An, you can refer to the Hue Dmz Tour from Hoian and Danang', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804870/danangtrip/tours/vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour/tour-020__vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour__p01__vmtravel-hue-dmz-tour-3.png', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804870/danangtrip/tours/vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour/tour-020__vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour__p01__vmtravel-hue-dmz-tour-3.png","https://res.cloudinary.com/dmukxquza/image/upload/v1780804873/danangtrip/tours/vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour/tour-020__vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour__p02__vmtravel-hue-dmz-tour.png","https://res.cloudinary.com/dmukxquza/image/upload/v1780804877/danangtrip/tours/vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour/tour-020__vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour__p03__vmtravel-hue-dmz-tour-1.png"]'::json, 'https://vmtravel.com/tours/hue-dmz-tour-deluxe-group-tour/', 1, 20),
    ('vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour', 'Hue Day Trip From Da Nang - Deluxe Small Group Tour', 'tour-hue', 'Chương trình tham quan Da Nang, Hoi An, Hue với thời lượng 1 day. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/hue-day-trip-from-da-nang/', 'Tour Da Nang, Hoi An, Hue, thời lượng 1 day, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["07:00 - 07:30 A.M: Our team will pick you up at your hotel in Da Nang.","08:30 A.M: We will arrive at the first stop in the itinerary, the Majestic Hai Van Pass. Are you ready to conquer one of the most remarkable coastal roads in the world? With approximately 30 minutes to savor this natural wonder, you''ll have the chance to capture some shots of the","After that, our car will continue to move to Lang Co Beach - one of the world''s most beautiful Bays in Hue. Here, we will pass over the serene Lap An Lagoon . The lagoon is famous for its poetic and peaceful beauty. You will have 10 minutes to capture the charming natural surroun","11:00 A.M: Welcome you to Hue City Center. Begin your journey to discover the beauty of Hue Imperial City by visiting Khai Dinh Tomb, the 12th King of the Nguyen Dynasty. Khai Dinh Tomb is distinctive in design from the traditional architecture of other royal tombs in Hue. The to","12:30 A.M: Having lunch at a local restaurant offering Hue specialties, including Hue Beef Noodles, Stuffed Rice Pancakes, Fried Spring Rolls, and many delicious traditional Hue cakes.","01:30 P.M: We continue the Hue Day Trip From Da Nang to the Imperial Citadel. This grandeur architecture is the seat of the capital of the Nguyen Dynasty, the last dynasty of Vietnam from 1802 to 1945. Wandering the peaceful royal garden, admire the ornate royal architecture, and","03:00 P.M: Visit Thien Mu Pagoda , the spiritual symbol of Hue City, with a seven-story height of 21m. The pagoda is 400 years old and next to the poetic Perfume River. Wandering under the green pines, enjoying the elegant smells of a lotus lake, observing the Buddhists praying,","04:00 P.M: Finish the sightseeing tour at some must-see destinations in Hue. Begin your return to Da Nang city.","06:00 P.M: Our team will drop you off at your hotel in Da Nang. Goodbye, thank you for choosing VM Travel to explore the ancient capital Hue from Da Nang, and see you again."]'::json, '["High-Quality Minivan","Live English Speaking Tour Guide","Local Lunch with Hue / Vietnam Cuisine","Entrance fees as Itinerary","Mineral Water 2 Bottle / 1 Day / 1 Pax"]'::json, '["Optional gratuities for driver and guide","Personal expenses and additional meals","Pick up from your hotel/stay outside the center of Da Nang City"]'::json, 1225000.0, 0.0, 0.0, 0, '1 day', NULL, 'departing one of the most dynamic cities in beautiful Vietnam, Da Nang, to the capital', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804880/danangtrip/tours/vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour/tour-021__vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour__p01__vmtravel-hue-city-tour-from-hoian.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804880/danangtrip/tours/vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour/tour-021__vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour__p01__vmtravel-hue-city-tour-from-hoian.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804883/danangtrip/tours/vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour/tour-021__vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour__p02__vmtravel-khai-dinh-tomb-tour.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804887/danangtrip/tours/vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour/tour-021__vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour__p03__vmtravel-hue-city-tour-1.png"]'::json, 'https://vmtravel.com/tours/hue-day-trip-from-da-nang/', 1, 21),
    ('vmtravel-central-017-hue-day-trip-from-da-nang-private-tour', 'Hue Day Trip From Da Nang - Private Tour', 'tour-hue', 'Chương trình tham quan Da Nang, Hoi An, Hue với thời lượng 1 Day. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/hue-day-trip-from-da-nang-private-tour/', 'Tour Da Nang, Hoi An, Hue, thời lượng 1 Day, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["Our driver and guide will pick you up at your hotel in Danang and transfer to Hue City. The journey is about 102km to the North of Danang. On the way, we will conquer the breathtaking Hai Van Pass - one of the world''s most scenic coastal routes. Stop to capture moments and admire","Enjoy a Cyclo Tour from the restaurant to Hue Imperial Citadel. You will feel the city''s fresh air by passing through green trees. Arrive at Hue Imperial Citadel - the cultural and political lasting 143 years of the last royal dynasty in Vietnam. Here, have a chance to learn abou","Finish the Hue Day Trip from Danang - Private Tour. Goodbye, and thank you for choosing VM Travel to explore the ancient beauty of Hue. See you again!","Note: We can provide vegetarian, halal, or accommodate any special dietary requests, please inform our sales team of your preferred food option"]'::json, '["High-Quality Transportation","Live English Speaking Tour Guide","Lunch with Vietnamese cuisine","Entrance fees as Itinerary","Mineral Water 2 Bottles / 1 day / 1 pax"]'::json, '["Optional tip for driver and guide","Personal expenses and additional meals","Pick up from the Hotel outside the city center"]'::json, 4125000.0, 0.0, 0.0, 0, '1 Day', NULL, NULL, 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804890/danangtrip/tours/vmtravel-central-017-hue-day-trip-from-da-nang-private-tour/tour-022__vmtravel-central-017-hue-day-trip-from-da-nang-private-tour__p01__vmtravel-hue-day-trip.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804890/danangtrip/tours/vmtravel-central-017-hue-day-trip-from-da-nang-private-tour/tour-022__vmtravel-central-017-hue-day-trip-from-da-nang-private-tour__p01__vmtravel-hue-day-trip.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804893/danangtrip/tours/vmtravel-central-017-hue-day-trip-from-da-nang-private-tour/tour-022__vmtravel-central-017-hue-day-trip-from-da-nang-private-tour__p02__vmtravel-hue-imperial-city-1.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804897/danangtrip/tours/vmtravel-central-017-hue-day-trip-from-da-nang-private-tour/tour-022__vmtravel-central-017-hue-day-trip-from-da-nang-private-tour__p03__vmtravel-hue-city-tour-6.png"]'::json, 'https://vmtravel.com/tours/hue-day-trip-from-da-nang-private-tour/', 1, 22),
    ('vmtravel-central-019-hue-day-trip-from-hoi-an-da-nang-book-best-1-day-group-tour', 'Hue Day Trip From Hoi An Da Nang-Book Best 1 Day Group Tour', 'tour-hue', 'Chương trình tham quan Da Nang, Hoi An, Hue với thời lượng 1 day. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/hue-day-trip-from-hoi-an/', 'Tour Da Nang, Hoi An, Hue, thời lượng 1 day, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["07:00 - 07:30 A.M: Our car and tour guide will pick you up at your hotel in Hoi An. Let’s start on your journey to the ancient capital of Hue, and do not miss out admire the beauty of nature through the window.","08:30 AM: We will arrive at the first stop in the journey, the Majestic Hai Van Pass. Are you ready to conquer one of the most remarkable coastal roads in the world? Here, you will have about 30 minutes to stop at the peak and take advantage of impressive shots with the \"million","After that, our car will move to Lang Co Beach - one of the world''s most beautiful Bays in Hue, and we will pass over the serene Lap An Lagoon. The lagoon is famous for its beauty as poetry. Get a camera ready, and you will have 10 minutes to capture the charming natural surround","11:00 AM: Welcome you to Hue City Center. Begin your journey to discover the beauty of Hue Imperial City by visiting Khai Dinh Tomb, the 12th King of the Nguyen Dynasty. The tomb''s design is unlike the traditional grandeur of other imperial tombs in Hue. The tomb is a fusion of t","12:30 AM: Having lunch at a local restaurant with Hue cuisine. Before your meals, relax your mind and feet after a long walk with the herbal footbath service from local natural herbs. Take a short break before continuing the trip back in time and explore the grandeur of the Hue I","01:30 PM: We continue the Hue Day Trip From Hoi An to the Imperial Citadel. This grandeur architecture is the capital of the Nguyen Dynasty, the last dynasty of Vietnam from 1802 to 1945. Excursion the serene royal garden, admire the ornate royal architecture, and listen to the k","03:00 PM: Finally, we will move to the final stop in the journey. Visit Thien Mu Pagoda - the largest pagoda and the iconic of Hue City. The pagoda is 400 years old and next to the poetic Perfume River. Wandering under the green pines, enjoying the elegant smells of Lotus Lake, a","04:00 PM: Finish the sightseeing tour at some must-see destinations in Hue. Begin your return to charming Hoi An.","07:00 PM: Our driver will drop you off at your hotel in Hoi An. Goodbye, thank you for choosing VM Travel to explore the ancient capital Hue from Hoi An, and see you again."]'::json, '["High-Quality Minivan","Live English Speaking Tour Guide","Local Lunch with Hue / Vietnam Cuisine","Herbal Foot Bath","Entrance fees as Itinerary","Mineral Water 2 Bottle / 1 Day / 1 Pax"]'::json, '["Optional gratuities for driver and guide","Personal expenses and additional meals","Pick up from your hotel/stay outside the center of Hue"]'::json, 1350000.0, 0.0, 0.0, 0, '1 day', NULL, 'departing one of the most charming towns in the world, Hoi An, to the site of the last', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804887/danangtrip/tours/vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour/tour-021__vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour__p03__vmtravel-hue-city-tour-1.png', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804887/danangtrip/tours/vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour/tour-021__vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour__p03__vmtravel-hue-city-tour-1.png","https://res.cloudinary.com/dmukxquza/image/upload/v1780804880/danangtrip/tours/vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour/tour-021__vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour__p01__vmtravel-hue-city-tour-from-hoian.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804900/danangtrip/tours/vmtravel-central-019-hue-day-trip-from-hoi-an-da-nang-book-best-1-day-group-tour/tour-023__vmtravel-central-019-hue-day-trip-from-hoi-an-da-nang-book-best-1-day-group-tour__p03__vmtravel-hue-city-tour-7.png"]'::json, 'https://vmtravel.com/tours/hue-day-trip-from-hoi-an/', 1, 23),
    ('vmtravel-recheck-005-hue-imperial-tour-from-chan-may-port-best-shore-excursions', 'Hue Imperial Tour from Chan May Port: Best Shore Excursions', 'tour-hue', 'Chương trình tham quan Da Nang, Hoi An, Hue với thời lượng 8 Hours. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/hue-imperial-tour-from-chan-may-port/', 'Tour Da Nang, Hoi An, Hue, thời lượng 8 Hours, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["08:00 – 09:00 AM | Seamless Port Pickup: We will meet you promptly between 8:00 AM and 9:00 AM at Chân Mây Port. For your convenience, you may choose either 1. Pickup inside the port or 2. Pickup just outside the port gate.","Arrival & Imperial Discovery: After an approximately one-hour scenic drive, we arrive at the heart of Hue and immediately dive into the city’s majestic past.","Khai Dinh Royal Tomb: Begin your exploration at this visually stunning royal resting place, famous for its unique blend of distinctive Western and Eastern architectural styles.","The Imperial Citadel: Step inside the ancient capital of Vietnam, a UNESCO World Heritage Site built by Emperor Gia Long in 1805. This powerful complex was the center of the Nguyễn Dynasty. You will explore numerous ramparts, palaces, and royal structures that remain nearly origi","Lunch & Relaxation: Enjoy a delicious lunch at a famous local garden restaurant, providing a refreshing culinary experience and a short, peaceful rest before continuing your journey.","Thien Mu Pagoda – The Spiritual Icon: Our afternoon starts at the oldest and most beautiful pagoda in Hue. Located just 3km from the Citadel on the northern bank of the Perfume River, Thien Mu Pagoda offers a tranquil atmosphere surrounded by ornamental plants. In the late aftern","Safe Return to Port: Following your spiritual visit, we will commence the drive back. You are guaranteed to arrive at the port at least one and a half hours before your ship''s departure time, ensuring a safe and stress-free return.","Tour Conclusion: The full-day historical experience concludes back at your Cruise ship, typically around 4:00 PM."]'::json, '["High-quality vehicle","Pick up and Drop off on time at Chan May Port","All the Entrance fees","Local Lunch","English speaking Guide during the trip"]'::json, '["Beverage in Meal","All Tips","+20 usd/pax if pick-up inside Port"]'::json, 4600000.0, 0.0, 0.0, 0, '8 Hours', NULL, 'Pickup', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804814/danangtrip/tours/vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass/tour-013__vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass__p02__vmtravel-hue-day-trip-from-chan-may-port.webp', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804814/danangtrip/tours/vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass/tour-013__vmtravel-central-011-da-nang-to-hue-day-trip-by-heritage-train-via-hai-van-pass__p02__vmtravel-hue-day-trip-from-chan-may-port.webp","https://res.cloudinary.com/dmukxquza/image/upload/v1780804904/danangtrip/tours/vmtravel-recheck-005-hue-imperial-tour-from-chan-may-port-best-shore-excursions/tour-024__vmtravel-recheck-005-hue-imperial-tour-from-chan-may-port-best-shore-excursions__p02__vmtravel-hue-imperial.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804908/danangtrip/tours/vmtravel-recheck-005-hue-imperial-tour-from-chan-may-port-best-shore-excursions/tour-024__vmtravel-recheck-005-hue-imperial-tour-from-chan-may-port-best-shore-excursions__p03__vmtravel-car-rental-from-port.jpg"]'::json, 'https://vmtravel.com/tours/hue-imperial-tour-from-chan-may-port/', 1, 24),
    ('vmtravel-central-021-hue-street-food-tour-explore-local-flavours-for-just-45', 'Hue Street Food Tour - Explore Local Flavours for Just $45', 'tour-am-thuc', 'Chương trình tham quan Da Nang, Hoi An, Hue với thời lượng 5 Hours. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/hue-street-food-tour/', 'Tour Da Nang, Hoi An, Hue, thời lượng 5 Hours, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["About 5:00 PM:","First Stop: Visit the local market (Dong Ba market)","On the way to the market, you will have a chance to cross the Truong Tien Bridge, a beautiful and historic bridge. Admire the charming beauty of the poetic Huong River, has created a special symbol of Hue City.","Begin the food tour with a visit to a bustling local market. Here, you''ll experience the vibrant atmosphere of Hue''s daily life. Your guide will introduce you to various fresh ingredients commonly used in Hue''s cuisine, and you might even get to taste some specialists here. You c","Second Stop: Hue''s Cakes","Head to a local restaurant known for its traditional rice cakes, \"bánh bèo\" (steamed rice cakes topped with dried shrimp), \"Banh Loc\" (filtered tapioca dumplings) and \"Banh Nam\" (flat rice dumplings filled with minced shrimp and pork). Learn about the history of these dishes whil","Third Stop: Hue beef noodle soup","No visit to Hue would be complete without trying the iconic Hue beef noodle soup (Bún bò Huế). Enjoy this spicy and rich soup at a local restaurant that specializes in the dish. Your guide will explain the significance of this soup in Hue cuisine. Walk around the Imperial Citadel","End your food tour with sweet soup (Che Hue) by visiting a local dessert stall.","End of the tour, your guide will take you back to your hotel or a central location in Hue."]'::json, '["English-speaking Vietnamese Food Enthusiast Guide","A bottle of water","All food listed above"]'::json, '["Personal Fees"]'::json, 1125000.0, 0.0, 0.0, 0, '5 Hours', NULL, 'Departure Time Finish Time Option 1 9', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804911/danangtrip/tours/vmtravel-central-021-hue-street-food-tour-explore-local-flavours-for-just-45/tour-025__vmtravel-central-021-hue-street-food-tour-explore-local-flavours-for-just-45__p01__vmtravel-hue-strees-food-tour.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804911/danangtrip/tours/vmtravel-central-021-hue-street-food-tour-explore-local-flavours-for-just-45/tour-025__vmtravel-central-021-hue-street-food-tour-explore-local-flavours-for-just-45__p01__vmtravel-hue-strees-food-tour.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804914/danangtrip/tours/vmtravel-central-021-hue-street-food-tour-explore-local-flavours-for-just-45/tour-025__vmtravel-central-021-hue-street-food-tour-explore-local-flavours-for-just-45__p02__vmtravel-hu-food-tour-from-danang.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804866/danangtrip/tours/vmtravel-central-016-hue-cooking-class-tour-from-market-to-table/tour-019__vmtravel-central-016-hue-cooking-class-tour-from-market-to-table__p03__vmtravel-cyclo-in-hue.jpg"]'::json, 'https://vmtravel.com/tours/hue-street-food-tour/', 1, 25),
    ('vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an', 'Linh Ung Pagoda & Marble Mountain tour from Hoi An', 'tour-hoi-an', 'Chương trình tham quan Da Nang, Hoi An, Hue, Marble Mountains, Son Tra với thời lượng 6 Hours. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/marble-mountain-tour-from-hoi-an/', 'Tour Da Nang, Hoi An, Hue, Marble Mountains, Son Tra, thời lượng 6 Hours, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["7:30 – 8:00 AM – Our friendly guide and driver will pick you up from your hotel in Hoi An in a comfortable air-conditioned vehicle. Sit back and enjoy the drive along the coastline as we head to Da Nang.","8:30 AM – Arrive at Linh Ung Pagoda, located on the peaceful Son Tra Peninsula. Here you’ll find the 67-metre-tall Lady Buddha statue, a symbol of protection for fishermen and sailors. Take your time walking through the tranquil gardens, admire the traditional architecture, and e","9:30 AM – We continue to the nearby Marble Mountains, a group of five limestone hills named after the five elements. You’ll explore sacred caves such as Huyen Khong Cave and Tang Chon Cave, where Buddhist statues and natural light combine to create a magical atmosphere. Climb up","Before leaving, you’ll have a chance to visit the famous Non Nuoc stone carving village, where skilled local artisans have created marble statues for centuries.","12:00 PM – We’ll stop at a local restaurant to enjoy a light Vietnamese lunch, featuring traditional dishes that are fresh, simple, and satisfying.","1:00 PM – After lunch, we’ll drive you back to your hotel in Hoi An, ending the tour with a heart full of peace and some incredible photos to remember the morning by."]'::json, '["Pick-up and drop-off from Hoi An hotels (city centre)","Comfortable air-conditioned transport","Friendly English-speaking tour guide","Entrance tickets to all sites","Bottled drinking water","Light Vietnamese lunch"]'::json, '["Personal expenses","Travel insurance","Extra drinks during lunch","Tips for guide and driver (optional)"]'::json, 700000.0, 0.0, 0.0, 0, '6 Hours', NULL, NULL, 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804917/danangtrip/tours/vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an/tour-026__vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an__p01__vmtravel-marble-mountain-tour-from-da-nang.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804917/danangtrip/tours/vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an/tour-026__vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an__p01__vmtravel-marble-mountain-tour-from-da-nang.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804920/danangtrip/tours/vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an/tour-026__vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an__p02__vmtravel-linh-ung-pagoda-danang-vietnam.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804923/danangtrip/tours/vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an/tour-026__vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an__p03__vmtravel-best-time-to-visit-linh-ung-pagoda-da-nang.jpg"]'::json, 'https://vmtravel.com/tours/marble-mountain-tour-from-hoi-an/', 1, 26),
    ('vmtravel-central-022-luxury-da-nang-golf-tour-6-days-5-nights-4-rounds', 'Luxury Da Nang Golf Tour 6 Days 5 Nights 4 Rounds', 'tour-golf', 'Chương trình tham quan Da Nang, Hoi An, Hue, Ba Na Hills với thời lượng 6 Days. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/luxury-da-nang-golf-tour-6-days/', 'Tour Da Nang, Hoi An, Hue, Ba Na Hills, thời lượng 6 Days, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["Our driver will pick you up at Danang International Airport. Welcome drink check in hotel in Da Nang city. Rest and relax at your leisure before beginning the exciting golf tour.","Have breakfast at hotel, and start relaxing and enjoyable morning at BRG Legend golf course for tee off. Legend Danang Golf Course’s chief feature is a 7,160 yard, 18 hole course, links-style layout that was designed in the true spirit of the game - blown - out bunkers, firm and","Rest and have lunch at restaurant after explore a culturally rich and vibrant land - Da Nang. Admire the enchanting beauty and peaceful atmosphere of natural mountains and water. Embark on a journey to Marble Mountain, a group of five hills made of limestone and marble. Learn abo","Back to hotel. Take a rest and dinner at hotel.","Breakfast at hotel and then we will drive you to Vinpearl Golf Nam Hoi An for tee off. Just 1 hour from Da Nang city. With its 18-hole par 72 course, golfers can enjoy varied terrain, long winding fairways, challenging large bunkers, and panoramic sea view. Both professional golf","After golfing, you can explore the VinWonder Nam Hoi An entertainment - is a complex of experiences, cultural art exploration combined with entertainment and visit River Safari Nam Hoi An is a \"common home\" for hundreds of individuals of rare animal species.","Then return to your hotel and spend your night in Da Nang.","Enjoy a delicious breakfast at hotel. Transfer to Bana Hills golf course for tee off. Enjoy the fresh morning air and play golf at Ba Na valley surrounded by green mountains. With 18-hole par 72 course, Bana Hills Golf Club offers a sense of conquest, joy, and excitement for all","Have lunch at local restaurant and spend time walking and having fun on the beautiful My Khe beach in the afternoon.","Overnight in Da Nang city at your leisure, you might experience a cruise and diner on the Han river, admire the vibrant city with brilliant lights."]'::json, '["Enthusiastic, friendly, experienced caddies at each golf course","Shared buggy at each golf course","All airport and golf course transfers by private car","Hotel 4 stars with breakfast included","Meals as mention","2 bottles of water/golfer/day tour on transfer (500ml/bottle)","01 bottle of water/pax/way of airport transfer (500ml/bottle)","Local knowledge, suggestions, and support throughout the trip","24/7 golf hotline staffed by knowledgeable service personnel","Professional English speaking tour guide for sightseeing tour"]'::json, '["All airfares, visa","Personal items, drinks, and gratuities","International bank fund transfer fees","Other things that are not mentioned in the inclusions list"]'::json, 17250000.0, 0.0, 0.0, 0, '6 Days', NULL, 'Departure Have breakfast and check out the hotel', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804926/danangtrip/tours/vmtravel-central-022-luxury-da-nang-golf-tour-6-days-5-nights-4-rounds/tour-027__vmtravel-central-022-luxury-da-nang-golf-tour-6-days-5-nights-4-rounds__p01__vmtravel-golf-in-hoi-an.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804926/danangtrip/tours/vmtravel-central-022-luxury-da-nang-golf-tour-6-days-5-nights-4-rounds/tour-027__vmtravel-central-022-luxury-da-nang-golf-tour-6-days-5-nights-4-rounds__p01__vmtravel-golf-in-hoi-an.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804929/danangtrip/tours/vmtravel-central-022-luxury-da-nang-golf-tour-6-days-5-nights-4-rounds/tour-027__vmtravel-central-022-luxury-da-nang-golf-tour-6-days-5-nights-4-rounds__p02__vmtravel-vietnam-luxury-golf-tour.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804842/danangtrip/tours/vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang/tour-016__vmtravel-central-001-highlight-the-4-days-deluxe-golf-tour-in-da-nang__p03__vmtravel-vietnam-golf-tour.jpg"]'::json, 'https://vmtravel.com/tours/luxury-da-nang-golf-tour-6-days/', 6, 27),
    ('vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an', 'My Son Sanctuary From Hoi An-Book Best 1 Day Tour in Hoi An', 'tour-heritage-path', 'Chương trình tham quan Da Nang, Hoi An, Hue, My Son, Cu Lao Cham với thời lượng Half day. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/my-son-sanctuary-from-hoi-an/', 'Tour Da Nang, Hoi An, Hue, My Son, Cu Lao Cham, thời lượng Half day, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["01:00 PM - 01:30 PM: Our car and tour guide will pick you up at your hotel in Hoi An to begin the journey back in time and explore the World Heritage Site - My Son Sanctuary.","03:00 PM: Arrive at My Son Sanctuary after one hour to go from Hoi An. Enjoy the stunning natural landscape, including Hoi An River’s system, spectacular mountains, and Cham Island on the way. You will have two hours to discover the spiritual site by walking through the ancient t","05:15 PM: We leave My Son Sanctuary. Our car takes you to the wharf for a boat trip back to charming Hoi An Ancient Town. On the cruise, you have an extraordinary chance to bask in the fresh air and tranquility vibe on the calm Thu Bon River. Also, get your camera ready to captur","06:30 PM: The boat arrives in Hoi An. Our car will drop you off at your hotel. Finish the My Son Sanctuary Tour From Hoi An. Goodbye, thank you for choosing VM Travel on the journey to explore the World Heritage Site, and see you again!"]'::json, '["High-Quality Minivan","Boat Trip on Thu Bon River","Live English Speaking Tour Guide","Entrance fees as Itinerary","Mineral Water 2 Bottle / 1 Day / 1 Pax"]'::json, '["Optional gratuities for driver and guide","Personal expenses and additional meals","Pick up from your hotel/stay outside the center of Hoi An"]'::json, 875000.0, 0.0, 0.0, 0, 'Half day', NULL, 'Departing from Hoi An Ancient Town, exploring one of Southeast Asia’s most outstanding', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804933/danangtrip/tours/vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an/tour-028__vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an__p01__vmtravel-sunrise-at-my-son-sanctuary.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804933/danangtrip/tours/vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an/tour-028__vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an__p01__vmtravel-sunrise-at-my-son-sanctuary.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804936/danangtrip/tours/vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an/tour-028__vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an__p02__vmtravel-myson-sanctuary.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804939/danangtrip/tours/vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an/tour-028__vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an__p03__vmtravel-tour-my-son-sanctuary-from-hoi-an.jpg"]'::json, 'https://vmtravel.com/tours/my-son-sanctuary-from-hoi-an/', 1, 28),
    ('vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now', 'My Son Sanctuary Tour From Tien Sa Port - Explore Now', 'tour-heritage-path', 'Chương trình tham quan Da Nang, Hoi An, Hue, My Son với thời lượng 1 Day. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/my-son-sanctuary-tour-from-tien-sa-port/', 'Tour Da Nang, Hoi An, Hue, My Son, thời lượng 1 Day, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["Our driver and guide will pick you up at Tien Sa Port with a welcome board with your name. You can choose Pickup inside of the port or Pickup outside of the port.","Then, transfer you to My Son Sanctuary. Enjoy the stunning natural landscape on the way. Upon arrival at My Son Holy Land, you will have two hours to discover the spiritual site by walking through the ancient temples, observing the elaborately carved architecture, and learning ab","Especially watching the charming Apsara dance performed with skilled dancers. After My Son''s exploration, enjoy a taste of Vietnam in a local restaurant. Then, leave My Son and head back to Tien Sa Port. Later, drop you off at the port before cruise departure.","Finish My Son Sanctuary Tour from Tien Sa Port. Goodbye, and thank you for choosing VM Travel - Vietnam Package Tours to explore the World Cultural Heritage Site. See you again!"]'::json, '["High-Quality Minivan","Live English Speaking Tour Guide","Local Dinner with Hoi An/ Vietnamese Cuisine","Entrance fees as Itinerary","Mineral Water 2 Bottle / 1 Day / 1 Pax"]'::json, '["Optional gratuities for driver and guide","Personal expenses and additional meals","Pick up from your hotel outside the city center"]'::json, 1350000.0, 0.0, 0.0, 0, '1 Day', NULL, 'Pickup inside of the port or Pickup outside of the port', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804943/danangtrip/tours/vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now/tour-029__vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now__p01__vmtravel-my-son-sanctuary.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804943/danangtrip/tours/vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now/tour-029__vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now__p01__vmtravel-my-son-sanctuary.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804946/danangtrip/tours/vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now/tour-029__vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now__p02__vmtravel-my-son-holyland-tour.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804949/danangtrip/tours/vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now/tour-029__vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now__p03__vmtravel-my-son-holyland.jpg"]'::json, 'https://vmtravel.com/tours/my-son-sanctuary-tour-from-tien-sa-port/', 1, 29),
    ('vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece', 'Paradise Cave Tour From Hue - Explore Nature''s Masterpiece', 'tour-hang-dong', 'Chương trình tham quan Da Nang, Hoi An, Hue với thời lượng 1 Day. Thông tin giá, lịch trình, dịch vụ bao gồm và không bao gồm được tổng hợp từ website công khai của đơn vị tổ chức, sau đó chuẩn hóa để phục vụ bước kiểm duyệt nội dung trước khi mở bán. Nguồn tham khảo: https://vmtravel.com/tours/paradise-cave-tour-from-hue/', 'Tour Da Nang, Hoi An, Hue, thời lượng 1 Day, sử dụng giá và lịch trình được xác minh từ nguồn của đơn vị tổ chức.', '["6:30 AM: Our driver will pick you up at the hotel in Hue and depart to Paradise Cave, located in Phong Nha Ke Bang National Park in Quang Binh province, Vietnam. The cave is about more than 200 km from Hue City, making it a popular tourist destination since its opening in 2010.","On the way, you will have a chance to stop at La Vang Holy Land - is an important and largest religious pilgrimage center for Catholics, located in Quang Tri Province. When passing through the historical relic cluster of Hien Luong Bridge and Ben Hai River, you will be introduced","Arrive in Phong Nha Town, have lunch at a local restaurant, take a short rest before beginning the exploring Paradise cave trip.","Continue transfer to Paradise Cave, which is considered one of the most beautiful caves in Quang Binh, and is also known as the \"Underground Palace\" because of its majestic beauty and massive, sophisticated cave architecture.","You can enjoy under the skylight in the cave, where sunlight shines through, creating a fascinating interplay of light and shadow. Explore the large chambers in the cave with sparkling, magical stalactites. Conquer 500 steps leading to the cave entrance.","After discovering Paradise Cave, back to Hue and our driver will drop you off at your hotel. End of the tour."]'::json, '["High-Quality Minivan","Golf car in Paradise Cave (Electrical car))","English-speaking tour guide during the trip","Entrance fees","Lunch","Mineral Water 2 Bottle / 1 Day / 1 Pax"]'::json, '["Personal expenses and additional meals","Pick up from your hotel/stay outside the center of Hue","Optional gratuities for driver and guide"]'::json, 1600000.0, 0.0, 0.0, 0, '1 Day', NULL, 'depart to Paradise Cave, located in Phong Nha Ke Bang National Park in Quang Binh prov', 30, 1, 'https://res.cloudinary.com/dmukxquza/image/upload/v1780804952/danangtrip/tours/vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece/tour-030__vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece__p01__vmtravel-paradise-cave-tour-from-hue.jpg', '["https://res.cloudinary.com/dmukxquza/image/upload/v1780804952/danangtrip/tours/vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece/tour-030__vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece__p01__vmtravel-paradise-cave-tour-from-hue.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804955/danangtrip/tours/vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece/tour-030__vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece__p02__vmtravel-paradise-cave-tour.jpg","https://res.cloudinary.com/dmukxquza/image/upload/v1780804959/danangtrip/tours/vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece/tour-030__vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece__p03__vmtravel-phong-nha-caves.jpg"]'::json, 'https://vmtravel.com/tours/paradise-cave-tour-from-hue/', 1, 30);

SELECT setval(
    pg_get_serial_sequence('tours', 'id'),
    GREATEST((SELECT COALESCE(MAX(id), 1) FROM tours), 1),
    true
);

INSERT INTO tours (
    name, slug, tour_category_id, description, short_desc, itinerary, inclusions,
    exclusions, price_adult, price_child, price_infant, discount_percent, duration,
    start_time, meeting_point, max_people, min_people, thumbnail, images, status,
    booking_availability, is_featured, is_hot, created_at, updated_at
)
SELECT
    source.name,
    source.slug,
    category.id,
    source.description,
    source.short_desc,
    source.itinerary,
    source.inclusions,
    source.exclusions,
    source.price_adult,
    source.price_child,
    source.price_infant,
    source.discount_percent,
    source.duration,
    source.start_time,
    source.meeting_point,
    source.max_people,
    source.min_people,
    source.thumbnail,
    source.images,
    'inactive',
    'open',
    false,
    false,
    NOW(),
    NOW()
FROM verified_real_tour_import source
JOIN tour_categories category ON category.slug = source.category_slug
ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name,
    tour_category_id = EXCLUDED.tour_category_id,
    description = EXCLUDED.description,
    short_desc = EXCLUDED.short_desc,
    itinerary = EXCLUDED.itinerary,
    inclusions = EXCLUDED.inclusions,
    exclusions = EXCLUDED.exclusions,
    price_adult = EXCLUDED.price_adult,
    price_child = EXCLUDED.price_child,
    price_infant = EXCLUDED.price_infant,
    discount_percent = EXCLUDED.discount_percent,
    duration = EXCLUDED.duration,
    start_time = EXCLUDED.start_time,
    meeting_point = EXCLUDED.meeting_point,
    max_people = EXCLUDED.max_people,
    min_people = EXCLUDED.min_people,
    thumbnail = EXCLUDED.thumbnail,
    images = EXCLUDED.images,
    updated_at = NOW();

