    ('vmtravel-central-020-hue-dmz-tour-unveiling-history-on-captivating-tour', 1, 20),
    ('vmtravel-central-018-hue-day-trip-from-da-nang-deluxe-small-group-tour', 1, 21),
    ('vmtravel-central-017-hue-day-trip-from-da-nang-private-tour', 1, 22),
    ('vmtravel-central-019-hue-day-trip-from-hoi-an-da-nang-book-best-1-day-group-tour', 1, 23),
    ('vmtravel-recheck-005-hue-imperial-tour-from-chan-may-port-best-shore-excursions', 1, 24),
    ('vmtravel-central-021-hue-street-food-tour-explore-local-flavours-for-just-45', 1, 25),
    ('vmtravel-central-023-linh-ung-pagoda-marble-mountain-tour-from-hoi-an', 1, 26),
    ('vmtravel-central-022-luxury-da-nang-golf-tour-6-days-5-nights-4-rounds', 6, 27),
    ('vmtravel-central-024-my-son-sanctuary-from-hoi-an-book-best-1-day-tour-in-hoi-an', 1, 28),
    ('vmtravel-recheck-004-my-son-sanctuary-tour-from-tien-sa-port-explore-now', 1, 29),
    ('vmtravel-central-025-paradise-cave-tour-from-hue-explore-nature-s-masterpiece', 1, 30)
),
future_dates AS (
    SELECT
        schedule_source.*,
        (
            date_trunc('week', CURRENT_DATE)::date
            + 5
            + (week_index * 7)
        )::date AS start_date,
        week_index
    FROM schedule_source
    CROSS JOIN generate_series(1, 8) AS week_index
)
INSERT INTO tour_schedules (
    tour_id, start_date, end_date, max_people, booked_people, price_adult,
    price_child, price_infant, status, booking_availability, departure_code,
    departure_place, booking_deadline, created_at, updated_at
)
SELECT
    tours.id,
    future_dates.start_date,
    future_dates.start_date + (future_dates.duration_days - 1),
    tours.max_people,
    0,
    tours.price_adult,
    tours.price_child,
    tours.price_infant,
    'available',
    'open',
    'REAL-' || lpad(future_dates.import_order::text, 2, '0')
        || '-' || to_char(future_dates.start_date, 'YYYYMMDD'),
    COALESCE(NULLIF(tours.meeting_point, ''), 'Đà Nẵng / điểm đón của đơn vị tổ chức'),
    (future_dates.start_date::timestamp - interval '18 hours'),
    NOW(),
    NOW()
FROM future_dates
JOIN tours ON tours.slug = future_dates.slug
ON CONFLICT (tour_id, start_date) DO NOTHING;

SELECT setval(
    pg_get_serial_sequence('tours', 'id'),
    GREATEST((SELECT MAX(id) FROM tours), 1),
    true
);

COMMIT;
